SET NAMES utf8mb4;
DROP DATABASE IF EXISTS corte_certo;
CREATE DATABASE corte_certo CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE corte_certo;

CREATE TABLE bairro (
  codigo        INT           NOT NULL AUTO_INCREMENT,
  nome          VARCHAR(60)   NOT NULL,
  regiao        VARCHAR(40)   NOT NULL,
  distancia_km  DECIMAL(4,1)  NOT NULL,
  PRIMARY KEY (codigo),
  CONSTRAINT uq_bairro_nome UNIQUE (nome),
  CONSTRAINT distancia_do_bairro CHECK (distancia_km >= 0)
) ENGINE=InnoDB;

CREATE TABLE cliente (
  codigo        INT           NOT NULL AUTO_INCREMENT,
  nome          VARCHAR(80)   NOT NULL,
  apelido       VARCHAR(40)       NULL,
  nascimento    DATE              NULL,
  bairro_id     INT           NOT NULL,
  indicado_por  INT               NULL,
  cadastrado_em DATE          NOT NULL,
  PRIMARY KEY (codigo),
  CONSTRAINT fk_cliente_bairro  FOREIGN KEY (bairro_id)    REFERENCES bairro (codigo),
  CONSTRAINT fk_cliente_cliente FOREIGN KEY (indicado_por) REFERENCES cliente (codigo)
) ENGINE=InnoDB;
-- RN-06 (ninguem indica a si mesmo) NAO entra como CHECK: o banco recusa CHECK
-- sobre coluna AUTO_INCREMENT (erro 1901). E regra de aplicacao, conferida por consulta.

CREATE TABLE telefone (
  codigo     INT         NOT NULL AUTO_INCREMENT,
  cliente_id INT         NOT NULL,
  numero     VARCHAR(20) NOT NULL,
  tipo       VARCHAR(20)     NULL,
  PRIMARY KEY (codigo),
  CONSTRAINT uq_telefone_numero UNIQUE (numero),
  CONSTRAINT fk_telefone_cliente FOREIGN KEY (cliente_id) REFERENCES cliente (codigo),
  CONSTRAINT tipo_do_telefone CHECK (tipo IN ('celular','fixo','recado','whatsapp'))
) ENGINE=InnoDB;

CREATE TABLE profissional (
  codigo              INT          NOT NULL AUTO_INCREMENT,
  nome                VARCHAR(80)  NOT NULL,
  apelido             VARCHAR(40)      NULL,
  especialidade       VARCHAR(30)  NOT NULL,
  comissao_percentual DECIMAL(5,2) NOT NULL,
  cadeira             VARCHAR(10)      NULL,
  admitido_em         DATE         NOT NULL,
  ativo               BOOLEAN      NOT NULL DEFAULT 1,
  PRIMARY KEY (codigo),
  CONSTRAINT uq_profissional_cadeira UNIQUE (cadeira),
  CONSTRAINT especialidade_do_profissional CHECK (especialidade IN ('cabelo','barba','unha','sobrancelha','trancas')),
  CONSTRAINT comissao_do_profissional CHECK (comissao_percentual >= 0 AND comissao_percentual <= 100),
  CONSTRAINT ativo_do_profissional CHECK (ativo IN (0,1))
) ENGINE=InnoDB;

CREATE TABLE servico (
  codigo          INT           NOT NULL AUTO_INCREMENT,
  descricao       VARCHAR(60)   NOT NULL,
  categoria       VARCHAR(30)   NOT NULL,
  preco           DECIMAL(10,2) NOT NULL,
  duracao_minutos INT           NOT NULL,
  PRIMARY KEY (codigo),
  CONSTRAINT uq_servico_descricao UNIQUE (descricao),
  CONSTRAINT preco_do_servico CHECK (preco > 0),
  CONSTRAINT duracao_do_servico CHECK (duracao_minutos > 0)
) ENGINE=InnoDB;

CREATE TABLE agendamento (
  numero          INT           NOT NULL AUTO_INCREMENT,
  cliente_id      INT           NOT NULL,
  profissional_id INT               NULL,
  inicio          DATETIME      NOT NULL,
  status          VARCHAR(12)   NOT NULL DEFAULT 'marcado',
  valor           DECIMAL(10,2) NOT NULL DEFAULT 0,
  observacao      VARCHAR(120)      NULL,
  PRIMARY KEY (numero),
  CONSTRAINT fk_agendamento_cliente      FOREIGN KEY (cliente_id)      REFERENCES cliente (codigo),
  CONSTRAINT fk_agendamento_profissional FOREIGN KEY (profissional_id) REFERENCES profissional (codigo),
  CONSTRAINT status_do_agendamento CHECK (status IN ('marcado','atendido','faltou','cancelado')),
  CONSTRAINT valor_do_agendamento CHECK (valor >= 0)
) ENGINE=InnoDB;

CREATE TABLE item_do_agendamento (
  agendamento_id INT           NOT NULL,
  servico_id     INT           NOT NULL,
  quantidade     INT           NOT NULL,
  preco_cobrado  DECIMAL(10,2) NOT NULL,
  PRIMARY KEY (agendamento_id, servico_id),
  CONSTRAINT fk_item_do_agendamento_agendamento FOREIGN KEY (agendamento_id) REFERENCES agendamento (numero),
  CONSTRAINT fk_item_do_agendamento_servico     FOREIGN KEY (servico_id)     REFERENCES servico (codigo),
  CONSTRAINT quantidade_do_item CHECK (quantidade > 0),
  CONSTRAINT preco_do_item CHECK (preco_cobrado > 0)
) ENGINE=InnoDB;

CREATE TABLE pagamento (
  codigo         INT           NOT NULL AUTO_INCREMENT,
  agendamento_id INT           NOT NULL,
  pago_em        DATETIME      NOT NULL,
  valor          DECIMAL(10,2) NOT NULL,
  forma          VARCHAR(10)   NOT NULL,
  PRIMARY KEY (codigo),
  CONSTRAINT fk_pagamento_agendamento FOREIGN KEY (agendamento_id) REFERENCES agendamento (numero),
  CONSTRAINT valor_do_pagamento CHECK (valor > 0),
  CONSTRAINT forma_do_pagamento CHECK (forma IN ('dinheiro','pix','cartao'))
) ENGINE=InnoDB;

CREATE TABLE produto (
  codigo         INT           NOT NULL AUTO_INCREMENT,
  descricao      VARCHAR(60)   NOT NULL,
  preco          DECIMAL(10,2) NOT NULL,
  estoque_minimo INT           NOT NULL DEFAULT 0,
  PRIMARY KEY (codigo),
  CONSTRAINT uq_produto_descricao UNIQUE (descricao),
  CONSTRAINT preco_do_produto CHECK (preco > 0),
  CONSTRAINT minimo_do_produto CHECK (estoque_minimo >= 0)
) ENGINE=InnoDB;

CREATE TABLE venda (
  numero         INT           NOT NULL AUTO_INCREMENT,
  cliente_id     INT               NULL,
  agendamento_id INT               NULL,
  vendido_em     DATETIME      NOT NULL,
  valor          DECIMAL(10,2) NOT NULL,
  PRIMARY KEY (numero),
  CONSTRAINT fk_venda_cliente     FOREIGN KEY (cliente_id)     REFERENCES cliente (codigo),
  CONSTRAINT fk_venda_agendamento FOREIGN KEY (agendamento_id) REFERENCES agendamento (numero),
  CONSTRAINT valor_da_venda CHECK (valor > 0)
) ENGINE=InnoDB;

CREATE TABLE item_da_venda (
  venda_id      INT           NOT NULL,
  produto_id    INT           NOT NULL,
  quantidade    INT           NOT NULL,
  preco_cobrado DECIMAL(10,2) NOT NULL,
  PRIMARY KEY (venda_id, produto_id),
  CONSTRAINT fk_item_da_venda_venda   FOREIGN KEY (venda_id)   REFERENCES venda (numero),
  CONSTRAINT fk_item_da_venda_produto FOREIGN KEY (produto_id) REFERENCES produto (codigo),
  CONSTRAINT quantidade_do_item_da_venda CHECK (quantidade > 0),
  CONSTRAINT preco_do_item_da_venda CHECK (preco_cobrado > 0)
) ENGINE=InnoDB;

CREATE TABLE movimento_de_estoque (
  codigo     INT         NOT NULL AUTO_INCREMENT,
  produto_id INT         NOT NULL,
  data       DATE        NOT NULL,
  tipo       VARCHAR(10) NOT NULL,
  quantidade INT         NOT NULL,
  motivo     VARCHAR(40)     NULL,
  PRIMARY KEY (codigo),
  CONSTRAINT fk_movimento_de_estoque_produto FOREIGN KEY (produto_id) REFERENCES produto (codigo),
  CONSTRAINT tipo_do_movimento CHECK (tipo IN ('entrada','saida')),
  CONSTRAINT quantidade_do_movimento CHECK (quantidade > 0)
) ENGINE=InnoDB;

CREATE TABLE avaliacao (
  codigo         INT          NOT NULL AUTO_INCREMENT,
  agendamento_id INT          NOT NULL,
  nota           INT          NOT NULL,
  comentario     VARCHAR(140)     NULL,
  avaliado_em    DATE         NOT NULL,
  PRIMARY KEY (codigo),
  CONSTRAINT uq_avaliacao_agendamento UNIQUE (agendamento_id),
  CONSTRAINT fk_avaliacao_agendamento FOREIGN KEY (agendamento_id) REFERENCES agendamento (numero),
  CONSTRAINT nota_da_avaliacao CHECK (nota BETWEEN 1 AND 5)
) ENGINE=InnoDB;
